// Suu v2 · "check my work" chat skill. The student types their solution steps; Suu finds the FIRST wrong
// step, says why, and shows the corrected step (without finishing the problem for them).
// Steps are generated by code: a correct chain, then (70% of the time) one classic mistake injected at a
// chosen step, and every later step continues from the wrong value — like a real student.
// No runtime imports (runs in Colab).
import { frac, int, mulberry32, nonZero, par, pick, type Rng, term } from '../pipeline/templates/shared';
import { CHAT_PROMPT, type Row } from './skills';

export type Chain = {
  family: string;
  prompt: string;
  steps: string[];
  answer: string;
  /** 0-based index of the first wrong step, or -1 when all steps are right. */
  wrong: number;
  why?: string;
  fix?: string;
};

const cx = (a: number, v = 'x') => (a === 1 ? v : a === -1 ? `-${v}` : `${a}${v}`);

/** ax + b = c */
function lin(r: Rng, err: number): Chain | null {
  const a = int(r, 2, 9);
  const x = int(r, -8, 12);
  const b = nonZero(r, -15, 15);
  const c = a * x + b;
  const prompt = `Solve for $x$: $${cx(a)} ${term(b)} = ${c}$`;
  const good = [`${cx(a)} = ${c - b}`, `x = ${x}`];
  const base: Chain = { family: 'lin', prompt, steps: good, answer: `x = ${x}`, wrong: -1 };
  if (err === 0) {
    const v = c + b;
    return {
      ...base,
      steps: [`${cx(a)} = ${v}`, `x = ${frac(v, a)}`],
      wrong: 0,
      why: `Нөгөө тал руу шилжүүлэхэд тэмдэг нь эсрэгээрээ болно: $${cx(a)} = ${c} ${term(-b)} = ${c - b}$.`,
      fix: good[0],
    };
  }
  if (err === 1) {
    if (c - b - a === x) return null;
    return {
      ...base,
      steps: [good[0] as string, `x = ${c - b - a}`],
      wrong: 1,
      why: `$${cx(a)}$ гэдэг нь $${a}$-г $x$-ээр үржүүлсэн. Тиймээс $${a}$-г хасах биш, хоёр талыг $${a}$-д хуваана.`,
      fix: good[1],
    };
  }
  return base;
}

/** a(x + b) = cx + d */
function dist(r: Rng, err: number): Chain | null {
  const a = int(r, 2, 6);
  const b = nonZero(r, -6, 6);
  const c = int(r, 1, 7);
  if (c === a || a - c === 1) return null;
  const x = int(r, -6, 9);
  const d = a * (x + b) - c * x;
  const k = a - c;
  if (d === 0) return null;
  const prompt = `Solve for $x$: $${a}(x ${term(b)}) = ${cx(c)} ${term(d)}$`;
  const good = [`${cx(a)} ${term(a * b)} = ${cx(c)} ${term(d)}`, `${cx(k)} = ${d - a * b}`, `x = ${x}`];
  const base: Chain = { family: 'dist', prompt, steps: good, answer: `x = ${x}`, wrong: -1 };
  if (err === 0) {
    const v = d - b;
    return {
      ...base,
      steps: [`${cx(a)} ${term(b)} = ${cx(c)} ${term(d)}`, `${cx(k)} = ${v}`, `x = ${frac(v, k)}`],
      wrong: 0,
      why: `Хаалтыг задлахдаа $${a}$-г хаалтан доторх гишүүн бүрээр үржүүлнэ: $${a} \\cdot ${par(b)} = ${a * b}$.`,
      fix: good[0],
    };
  }
  if (err === 1) {
    const v = d + a * b;
    return {
      ...base,
      steps: [good[0] as string, `${cx(k)} = ${v}`, `x = ${frac(v, k)}`],
      wrong: 1,
      why: `$${a * b}$-г баруун тал руу шилжүүлэхэд тэмдэг нь өөрчлөгдөнө: $${d} ${term(-a * b)}$.`,
      fix: good[1],
    };
  }
  if (err === 2) {
    if (d - a * b - k === x) return null;
    return {
      ...base,
      steps: [good[0] as string, good[1] as string, `x = ${d - a * b - k}`],
      wrong: 2,
      why: `$${cx(k)}$-ээс $x$-ийг олохдоо $${k}$-г хасах биш, хоёр талыг $${k}$-д хуваана.`,
      fix: good[2],
    };
  }
  return base;
}

/** Price up r%, then down s%. */
function pct(r: Rng, err: number): Chain | null {
  const p = 100 * int(r, 2, 10);
  const up = pick(r, [10, 20, 25, 50] as const);
  const down = pick(r, [10, 20, 25, 50] as const);
  const v1 = (p * (100 + up)) / 100;
  const v2 = (v1 * (100 - down)) / 100;
  if (!Number.isInteger(v2)) return null;
  const m1 = (100 + up) / 100;
  const m2 = (100 - down) / 100;
  const prompt = `A jacket costs \\$${p}. The price is increased by ${up}% and then the new price is decreased by ${down}%. What is the final price?`;
  const good = [`${p} \\cdot ${m1} = ${v1}`, `${v1} \\cdot ${m2} = ${v2}`];
  const base: Chain = { family: 'pct', prompt, steps: good, answer: `${v2}`, wrong: -1 };
  if (err === 0) {
    const w1 = (p * up) / 100;
    const w2 = (w1 * (100 - down)) / 100;
    return {
      ...base,
      steps: [`${p} \\cdot ${up / 100} = ${w1}`, `${w1} \\cdot ${m2} = ${Number(w2.toFixed(2))}`],
      wrong: 0,
      why: `$${p} \\cdot ${up / 100}$ нь зөвхөн өсөлтийн хэмжээ. Шинэ үнэ = анхны үнэ + өсөлт, тиймээс $${m1}$-ээр үржүүлнэ.`,
      fix: good[0],
    };
  }
  if (err === 1) {
    const w2 = v1 - (p * down) / 100;
    if (w2 === v2) return null;
    return {
      ...base,
      steps: [good[0] as string, `${v1} - ${(p * down) / 100} = ${w2}`],
      wrong: 1,
      why: `${down}%-ийн хямдрал шинэ үнээс ($${v1}$) тооцогдоно, анхны үнээс ($${p}$) биш.`,
      fix: good[1],
    };
  }
  return base;
}

/** Slope through two points. */
function slope(r: Rng, err: number): Chain | null {
  const x1 = int(r, -6, 6);
  const x2 = int(r, -6, 8);
  const y1 = int(r, -9, 9);
  const y2 = int(r, -9, 9);
  const dx = x2 - x1;
  const dy = y2 - y1;
  if (dx === 0 || dy === 0 || Math.abs(dx) === Math.abs(dy)) return null;
  const prompt = `What is the slope of the line through $(${x1}, ${y1})$ and $(${x2}, ${y2})$?`;
  const setup = `m = \\frac{${y2} - ${par(y1)}}{${x2} - ${par(x1)}}`;
  const good = [setup, `m = ${frac(dy, dx)}`];
  const base: Chain = { family: 'slope', prompt, steps: good, answer: `m = ${frac(dy, dx)}`, wrong: -1 };
  if (err === 0) {
    return {
      ...base,
      steps: [`m = \\frac{${x2} - ${par(x1)}}{${y2} - ${par(y1)}}`, `m = ${frac(dx, dy)}`],
      wrong: 0,
      why: 'Налуу = $y$-ийн өөрчлөлт / $x$-ийн өөрчлөлт. Дээр нь $y$-үүд, доор нь $x$-үүд байна.',
      fix: good[0],
    };
  }
  if (err === 1) {
    if (y1 >= 0 && x1 >= 0) return null;
    const wdy = y1 < 0 ? y2 - -y1 : dy;
    const wdx = x1 < 0 ? x2 - -x1 : dx;
    if (wdx === 0 || frac(wdy, wdx) === frac(dy, dx)) return null;
    return {
      ...base,
      steps: [setup, `m = ${frac(wdy, wdx)}`],
      wrong: 1,
      why: 'Сөрөг тоог хасахад нэмэх болно: $a - (-b) = a + b$. Хүртвэр, хуваарийг дахин бод.',
      fix: good[1],
    };
  }
  return base;
}

/** x² + bx + c = 0 with integer roots. */
function quad(r: Rng, err: number): Chain | null {
  const p = nonZero(r, -9, 9);
  const q = nonZero(r, -9, 9);
  if (p === q || p === -q) return null;
  const b = -(p + q);
  const c = p * q;
  const eq = `x^2 ${b === 0 ? '' : b < 0 ? `- ${cx(-b)}` : `+ ${cx(b)}`} ${term(c)} = 0`.replace('  ', ' ');
  const prompt = `Solve $${eq}$.`;
  const [lo, hi] = p < q ? [p, q] : [q, p];
  const good = [`(x ${term(-lo)})(x ${term(-hi)}) = 0`, `x = ${lo}`, `x = ${hi}`];
  const shown = [good[0] as string, `x = ${lo} \\text{ эсвэл } x = ${hi}`];
  const base: Chain = {
    family: 'quad',
    prompt,
    steps: shown,
    answer: `x = ${lo}, x = ${hi}`,
    wrong: -1,
  };
  if (err === 0) {
    return {
      ...base,
      steps: [`(x ${term(lo)})(x ${term(hi)}) = 0`, `x = ${-hi} \\text{ эсвэл } x = ${-lo}`],
      wrong: 0,
      why: `Задаргааг үржүүлж шалга: дунд гишүүн нь $${b > 0 ? '+' : '-'}${cx(Math.abs(b))}$ гарах ёстой. Тоонуудын үржвэр $${c}$, нийлбэр $${-b}$.`,
      fix: good[0],
    };
  }
  if (err === 1) {
    return {
      ...base,
      steps: [good[0] as string, `x = ${-lo} \\text{ эсвэл } x = ${-hi}`],
      wrong: 1,
      why: `$(x ${term(-lo)}) = 0$ бол $x = ${lo}$: хаалтан доторх тооны эсрэг тэмдэгтэй утга шийд болно.`,
      fix: shown[1],
    };
  }
  return base;
}

/** x + y = s, x − y = d by adding. */
function sys(r: Rng, err: number): Chain | null {
  const X = int(r, -6, 12);
  const Y = int(r, -6, 12);
  if (X === Y) return null;
  const s = X + Y;
  const d = X - Y;
  const prompt = `If $x + y = ${s}$ and $x - y = ${d}$, what is the value of $y$?`;
  const good = [`2x = ${s + d}`, `x = ${X}`, `y = ${s} - ${par(X)} = ${Y}`];
  const base: Chain = { family: 'sys', prompt, steps: good, answer: `y = ${Y}`, wrong: -1 };
  if (err === 0) {
    const v = s - d;
    if (v % 2 !== 0) return null;
    const wx = v / 2;
    return {
      ...base,
      steps: [`2x = ${v}`, `x = ${wx}`, `y = ${s} - ${par(wx)} = ${s - wx}`],
      wrong: 0,
      why: `Хоёр тэгшитгэлийг нэмэхэд $y$ устна: зүүн тал $2x$, баруун тал $${s} ${term(d)} = ${s + d}$.`,
      fix: good[0],
    };
  }
  if (err === 2) {
    if (X === 0) return null;
    return {
      ...base,
      steps: [good[0] as string, good[1] as string, `y = ${s} + ${par(X)} = ${s + X}`],
      wrong: 2,
      why: `$x + y = ${s}$ бол $y = ${s} - x$. $x$-ийг нөгөө тал руу шилжүүлэхэд хасах болно.`,
      fix: good[2],
    };
  }
  return base;
}

/** Each family and the step indexes where it can inject a mistake. */
const FAMILIES: { make: (r: Rng, err: number) => Chain | null; errs: number[] }[] = [
  { make: lin, errs: [0, 1] },
  { make: dist, errs: [0, 1, 2] },
  { make: pct, errs: [0, 1] },
  { make: slope, errs: [0, 1] },
  { make: quad, errs: [0, 1] },
  { make: sys, errs: [0, 2] },
];

export const CHECK_ASKS = [
  'Миний бодолтыг шалгаад өгөөч.',
  'Алдаа маань хаана байна?',
  'Энэ зөв үү? Шалгаач.',
  'Хаана буруу бодсоноо олж чадахгүй байна.',
  'Mini bodoltiig shalgaad ogooch.',
  'Aldaa maan haana baina?',
] as const;
const PRAISE = ['Сайн байна!', 'Маш цэвэрхэн бодсон байна!', 'Яг зөв!'] as const;

export function randomChain(r: Rng): Chain {
  for (;;) {
    const fam = pick(r, FAMILIES);
    const err = r() < 0.3 ? -1 : pick(r, fam.errs);
    const c = fam.make(r, err);
    if (c) return c;
  }
}

export function chainMessages(c: Chain, ask: string, praise: string) {
  const work = c.steps.map((s, i) => `${i + 1}) $${s}$`).join('\n');
  const user = `${c.prompt}\n\nМиний бодолт:\n${work}\n\n${ask}`;
  const reply =
    c.wrong < 0
      ? `Бүх алхам зөв ✓ ${praise} Хариу: $${c.answer}$.`
      : `Алдаа **${c.wrong + 1}-р алхамд** байна. ${c.why}\nЗөв нь: $${c.fix}$\nЭндээс үргэлжлүүлээд дахин бодоод үз!`;
  return { user, reply };
}

export function stepcheckRows(seed: number, count: number, prefix = 'step'): Row[] {
  const r = mulberry32(seed);
  const seen = new Set<string>();
  const out: Row[] = [];
  while (out.length < count) {
    const c = randomChain(r);
    if (seen.has(c.prompt + c.wrong)) continue;
    seen.add(c.prompt + c.wrong);
    const { user, reply } = chainMessages(c, pick(r, CHECK_ASKS), pick(r, PRAISE));
    out.push({
      skill: 'stepcheck',
      id: `${prefix}-${seed}-${out.length}`,
      messages: [
        { role: 'system', content: CHAT_PROMPT },
        { role: 'user', content: user },
        { role: 'assistant', content: reply },
      ],
      check: { wrong: c.wrong, family: c.family, prompt: c.prompt },
    });
  }
  return out;
}

// ——— checking a model's reply ———

export type StepScore = { said: 'ok' | 'step' | 'none'; ok: boolean; step: boolean; pass: boolean };

/** Reads the verdict from the reply: "Бүх алхам зөв" or the first "N-р алхам". */
export function verdict(text: string): { kind: 'ok' | 'step' | 'none'; step?: number } {
  const m = /(\d+)\s*-?\s*р\s+алхам/.exec(text);
  if (m) return { kind: 'step', step: Number(m[1]) - 1 };
  if (/бүх алхам зөв/i.test(text)) return { kind: 'ok' };
  return { kind: 'none' };
}

export function scoreStep(output: string, wrong: number): StepScore {
  const v = verdict(output);
  const ok = wrong < 0 ? v.kind === 'ok' : v.kind === 'step';
  const step = wrong < 0 ? v.kind === 'ok' : v.step === wrong;
  return { said: v.kind, ok, step, pass: ok && step };
}
